pragma solidity ^0.7.5;
pragma abicoder v2;

import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import {SwapRouter} from "@v3-periphery/contracts/SwapRouter.sol";

contract ApprovalSwapRouter {
    SwapRouter immutable UNISWAP_ROUTER;

    constructor(SwapRouter _UNISWAP_ROUTER) {
        UNISWAP_ROUTER = _UNISWAP_ROUTER;
    }

    function exactInputSingle(
        SwapRouter.ExactInputSingleParams calldata params
    ) external payable returns (uint256 amountOut) {
        // Approve input token
        ERC20 tokenIn = ERC20(params.tokenIn);
        tokenIn.approve(address(UNISWAP_ROUTER), type(uint256).max);

        // Execute swap
        amountOut = UNISWAP_ROUTER.exactInputSingle(params);
    }
}

